class Solution {
public:
    int numSub(string s) {
        const int MOD = 1000000007;
        long long ans = 0;
        int n = s.size();
        int i = 0;
        while (i < n) {
            if (s[i] == '1') {
                long long cnt = 0;
                while (i < n && s[i] == '1') {
                    cnt++;
                    i++;
                }
                ans = (ans + cnt * (cnt + 1) / 2) % MOD;
            } else {
                i++;
            }
        }
        return (int)ans;
    }
};
